import { randomBytes } from 'node:crypto';
import { STAGES, PRODUCT } from '../core/constants.mjs';
import { escapeHtml } from '../core/security.mjs';
export { escapeHtml };

const safeJson=(value)=>JSON.stringify(value??{}).replaceAll('<','\\u003c').replaceAll('>','\\u003e').replaceAll('&','\\u0026');
const short=(value,size=12)=>String(value??'').slice(0,size);
const badge=(label,tone='neutral')=>`<span class="badge ${tone}">${escapeHtml(label)}</span>`;

function latestByStage(gates=[]){const map=new Map();for(const gate of gates)map.set(gate.stage,gate);return map;}
function stageTone(stage,current,gates){const gate=gates.get(stage);if(stage===current)return gate?.status==='fail'||gate?.status==='blocked'?'danger':'active';if(gate?.status==='pass')return 'pass';if(gate?.status==='stale')return 'stale';if(gate?.status==='fail'||gate?.status==='blocked')return 'danger';return 'pending';}
function proofLine(item){const producer=item.producer?.id??'unknown producer';const subject=item.subject?.artifactId?`artifact ${short(item.subject.artifactId)}`:`revision ${item.subject?.semanticRevision??'?'}`;return `${producer} · ${subject} · ${short(item.sha256,10)}`;}

export function renderForgeStudioHtml(state={}){
  const projects=state.projects?.length?state.projects:(state.project?[state.project]:[]);
  const project=state.project??projects[0]??{id:'standalone',name:'ForgeOS Workspace',stage:'intent',assurance:'A1',domain:'all',revision:0,semanticRevision:0,ideas:[],artifacts:[],evidence:[],gates:[],findings:[],risks:[],routes:[]};
  const federation=state.federation??{sourceCount:0,capabilityCount:0,providerCount:0,statusCounts:{},catalogRevision:0,blockerCount:0};
  const skillIntelligence=state.skillIntelligence??{outcomeCount:1024,techniqueCount:0,l0TechniqueCount:0,l1TechniqueCount:0,kernelTechniqueCount:0,evaluatorCount:0,stableProceduralProviders:0,candidateProceduralProviders:0};
  const v06=state.v06??{version:PRODUCT.version,kernelTechniqueCount:0,l0TechniqueCount:0,l1TechniqueCount:0,executionGraphVersion:2,reviewBenchmark:{cases:0,precision:0},agentSurfaceAdversarial:{cases:0,passed:0}};
  const routes=state.routes??project.routes?.at?.(-1)?.routes??[];
  const gateMap=latestByStage(project.gates??[]);
  const currentGate=gateMap.get(project.stage);
  const nonce=randomBytes(18).toString('base64url');
  const csp=`default-src 'none'; img-src 'self' data:; style-src 'nonce-${nonce}'; script-src 'nonce-${nonce}'; connect-src 'self'; font-src data:; frame-ancestors 'self' https://chatgpt.com https://chat.openai.com`;
  const projectOptions=projects.map(p=>`<option value="${escapeHtml(p.id)}"${p.id===project.id?' selected':''}>${escapeHtml(p.name)} · ${escapeHtml(p.stage)}</option>`).join('');
  const lifecycle=STAGES.map((stage,index)=>{const gate=gateMap.get(stage);const tone=stageTone(stage,project.stage,gateMap);const detail=gate?`${gate.status} ${gate.score}%`:'not evaluated';return `<li class="stage ${tone}" title="${escapeHtml(detail)}"><span>${String(index+1).padStart(2,'0')}</span><strong>${escapeHtml(stage)}</strong><small>${escapeHtml(gate?.status??'—')}</small></li>`;}).join('');
  const ideas=(project.ideas??[]).length?(project.ideas??[]).map(idea=>`<article class="card idea"><div class="eyebrow">cluster ${escapeHtml(short(idea.fingerprint,10))}</div><h3>${escapeHtml(idea.title)}</h3><p>${escapeHtml(idea.thesis)}</p><dl><dt>Mechanism</dt><dd>${escapeHtml(idea.mechanism??'Not recorded')}</dd><dt>Experiment</dt><dd>${escapeHtml(idea.cheapestExperiment??'Not recorded')}</dd></dl></article>`).join(''):'<div class="empty">No idea genomes recorded.</div>';
  const artifacts=(project.artifacts??[]).slice(-12).map(item=>{const links=(item.consumes??[]).map(id=>short(id,9)).join(', ')||'root';return `<li class="artifact-node"><div><strong>${escapeHtml(item.type)}</strong><small>${escapeHtml(item.id)} · v${escapeHtml(item.version??1)}</small><small>← ${escapeHtml(links)}</small></div><div>${badge(item.state??'draft',item.state==='verified'?'pass':item.state==='invalidated'?'danger':item.state==='superseded'?'stale':'neutral')}<code>${escapeHtml(short(item.sha256,10))}</code></div></li>`;}).join('')||'<li class="muted">No artifacts.</li>';
  const evidence=(project.evidence??[]).slice(-12).map(item=>`<li><div><strong>${escapeHtml(item.title??item.type)}</strong><small>${escapeHtml(proofLine(item))}</small></div>${badge(item.status??'unverified',item.status==='pass'?'pass':item.status==='fail'?'danger':'warn')}</li>`).join('')||'<li class="muted">No proof records.</li>';
  const riskItems=[...(project.findings??[]).map(x=>({...x,kind:'finding'})),...(project.risks??[]).map(x=>({...x,kind:'risk'}))].slice(-12);
  const findings=riskItems.map(item=>`<li><div><strong>${escapeHtml(item.title??item.description??item.id)}</strong><small>${escapeHtml(item.kind)} · ${escapeHtml(item.category??'general')}</small></div>${badge(`${item.severity??'unknown'}/${item.status??'open'}`,item.severity==='critical'?'danger':item.status==='closed'?'pass':'warn')}</li>`).join('')||'<li class="muted">No findings or risks.</li>';
  const routeCards=routes.length?routes.map((route,index)=>`<article class="route" data-skill="${escapeHtml(route.name)}"><span>${index+1}</span><div><strong>${escapeHtml(route.name)}</strong><small>${escapeHtml((route.reasons??[]).slice(0,3).join(' · '))}</small></div><em>${escapeHtml(route.score)}</em><button data-action="inspect" data-skill="${escapeHtml(route.name)}">Inspect</button><button data-action="start" data-skill="${escapeHtml(route.name)}" data-outputs="${escapeHtml(JSON.stringify(route.produces??[]))}">Start</button></article>`).join(''):'<div class="empty">Run the router to compute a typed path.</div>';
  const failed=(currentGate?.rules??[]).filter(rule=>!rule.passed);
  const gateDetails=currentGate?`<div class="gate-summary"><div>${badge(currentGate.status,currentGate.status==='pass'?'pass':currentGate.status==='stale'?'stale':'danger')}<strong>${currentGate.score}%</strong><span>semantic r${currentGate.evaluatedSemanticRevision}</span><code>${escapeHtml(short(currentGate.inputSha256,12))}</code></div>${failed.length?`<ul>${failed.map(rule=>`<li><strong>${escapeHtml(rule.id)}</strong> — ${escapeHtml(rule.remediation)}</li>`).join('')}</ul>`:'<p>All mandatory rules passed for this revision.</p>'}</div>`:'<div class="empty">Current gate has not been evaluated.</div>';
  const embedded=safeJson({tenantId:state.tenantId??'default',projects,project,routes});
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="${escapeHtml(csp)}"><title>ForgeOS Studio</title><style nonce="${nonce}">
:root{color-scheme:dark;--bg:#060913;--panel:#0d1425;--panel2:#121c32;--line:#293650;--text:#f6f8ff;--muted:#91a0ba;--cyan:#63e6ff;--violet:#a78bfa;--green:#62eda8;--amber:#ffd166;--red:#ff6b81}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#15284d 0,transparent 34%),radial-gradient(circle at 100% 8%,#35194f 0,transparent 30%),var(--bg);color:var(--text);font:14px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}.shell{max-width:1540px;margin:auto;padding:24px}.hero,.panel,.rail{border:1px solid var(--line);background:rgba(13,20,37,.92);backdrop-filter:blur(16px);border-radius:22px}.hero{padding:26px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:end;background:linear-gradient(135deg,rgba(99,230,255,.10),rgba(167,139,250,.13))}.brand,.eyebrow{font:800 11px ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase;color:var(--cyan)}h1{font-size:clamp(34px,5vw,70px);line-height:.95;letter-spacing:-.06em;margin:8px 0}p{color:var(--muted)}.selector{display:grid;gap:7px;min-width:260px}.selector select{background:#0a1020;color:var(--text);border:1px solid var(--line);padding:11px;border-radius:10px}.metrics{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.metric{padding:9px 12px;background:#080e1b;border:1px solid var(--line);border-radius:12px}.metric strong{display:block;font-size:17px}.metric span,small{display:block;color:var(--muted);font-size:10px}.layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:16px;margin-top:16px}.rail{padding:12px;height:max-content;position:sticky;top:12px}.stage-list,.list{list-style:none;padding:0;margin:0;display:grid;gap:7px}.stage{display:grid;grid-template-columns:25px 1fr auto;gap:8px;align-items:center;padding:8px;border-radius:10px;color:var(--muted)}.stage.pass{color:var(--green)}.stage.active{background:rgba(99,230,255,.12);box-shadow:inset 3px 0 var(--cyan);color:var(--text)}.stage.danger{color:var(--red)}.stage.stale{color:var(--amber)}.content{display:grid;gap:16px}.panel{padding:18px}.panel-head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:12px}.panel h2{margin:3px 0;font-size:17px}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.action,.route button{border:1px solid #385070;border-radius:10px;padding:9px 12px;font-weight:750;cursor:pointer;background:#192641;color:var(--text)}.action.primary{background:linear-gradient(135deg,var(--cyan),#7c9dff);color:#05101c;border:0}.action:disabled,.route button:disabled{opacity:.45;cursor:wait}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.span8{grid-column:span 8}.span7{grid-column:span 7}.span5{grid-column:span 5}.span6{grid-column:span 6}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:11px}.card{padding:15px;background:var(--panel2);border:1px solid #2b3b5a;border-radius:15px}.card h3{margin:7px 0}.card p{margin:0 0 12px}.card dl{display:grid;gap:4px;margin:0}.card dt{font-size:10px;color:var(--cyan);text-transform:uppercase}.card dd{margin:0 0 8px;color:#cbd5e6}.list li{display:flex;justify-content:space-between;gap:12px;padding:10px;background:#09101e;border:1px solid #202d46;border-radius:11px}.list code,.gate-summary code{color:var(--violet);font-family:ui-monospace,monospace}.artifact-node>div:last-child{text-align:right}.badge{display:inline-flex;padding:3px 7px;border:1px solid #40506d;border-radius:999px;font-size:9px;text-transform:uppercase;letter-spacing:.08em}.badge.pass{color:var(--green);border-color:#26704c}.badge.warn,.badge.stale{color:var(--amber);border-color:#725a22}.badge.danger{color:var(--red);border-color:#733347}.routes{display:grid;gap:8px}.route{display:grid;grid-template-columns:26px minmax(0,1fr) auto auto auto;gap:8px;align-items:center;background:#09101e;border:1px solid #273752;border-radius:11px;padding:9px}.route>span{color:var(--cyan);font-family:ui-monospace,monospace}.route em{color:var(--violet);font-style:normal}.empty,.muted{color:var(--muted);border:1px dashed #34425d;border-radius:11px;padding:13px}.gate-summary>div{display:flex;align-items:center;gap:10px}.gate-summary ul{color:var(--muted)}#status{min-height:22px;color:var(--muted)}#status.error{color:var(--red)}#status.success{color:var(--green)}.dialog{white-space:pre-wrap;max-height:300px;overflow:auto;background:#080d18;padding:12px;border-radius:10px;color:#dbe5f5}@media(max-width:930px){.hero{grid-template-columns:1fr}.layout{grid-template-columns:1fr}.rail{position:static}.stage-list{grid-template-columns:repeat(2,1fr)}.span8,.span7,.span5,.span6{grid-column:1/-1}}@media(max-width:560px){.shell{padding:10px}.panel,.hero{padding:14px}.stage-list{grid-template-columns:1fr}.route{grid-template-columns:24px 1fr auto}.route button{grid-column:span 1}}
</style></head><body><div class="shell"><header class="hero"><div><div class="brand">ForgeOS · Evidence-backed product engineering</div><h1 id="project-name">${escapeHtml(project.name)}</h1><p>Typed artifacts, independent gates, measurable skill utility, and protocol-native agent collaboration.</p><div class="metrics"><div class="metric"><strong id="metric-stage">${escapeHtml(project.stage)}</strong><span>stage</span></div><div class="metric"><strong>${escapeHtml(project.assurance??'A1')}</strong><span>assurance</span></div><div class="metric"><strong>${escapeHtml(project.domain??'all')}</strong><span>domain</span></div><div class="metric"><strong id="metric-revision">r${project.revision??0}/s${project.semanticRevision??0}</strong><span>revision</span></div></div></div><label class="selector">Project<select id="project-selector">${projectOptions||`<option value="${escapeHtml(project.id)}">${escapeHtml(project.name)}</option>`}</select></label></header><div class="layout"><nav class="rail" aria-label="Project lifecycle"><ol class="stage-list">${lifecycle}</ol></nav><main class="content"><section class="panel"><div class="panel-head"><div><div class="eyebrow">Control plane</div><h2>Next verified move</h2></div><div id="status" role="status" aria-live="polite">Ready.</div></div><div class="toolbar"><button id="next" class="action primary">Route next skills</button><button id="gate" class="action">Run current gate</button><button id="refresh" class="action">Refresh project</button></div><div id="gate-details">${gateDetails}</div><div id="routes" class="routes">${routeCards}</div><pre id="inspector" class="dialog" hidden></pre></section><div class="grid"><section class="panel span8"><div class="eyebrow">Novelty engine</div><h2>Mechanism-distinct ideas</h2><div class="cards">${ideas}</div></section><section class="panel span4"><div class="eyebrow">Artifact DAG</div><h2>Lineage and active versions</h2><ul class="list">${artifacts}</ul></section><section class="panel span7"><div class="eyebrow">Proof ledger</div><h2>Subject-bound evidence</h2><ul class="list">${evidence}</ul></section><section class="panel span5"><div class="eyebrow">Risk console</div><h2>Findings and residual risks</h2><ul class="list">${findings}</ul></section><section class="panel span12" id="federation-panel"><div class="panel-head"><div><div class="eyebrow">Skill Federation</div><h2>1K Capability Graph</h2></div><button id="federation-audit" class="action">Refresh federation audit</button></div><div class="metrics"><div class="metric"><strong id="federation-capabilities">${escapeHtml(federation.capabilityCount??0)}</strong><span>capabilities</span></div><div class="metric"><strong id="federation-sources">${escapeHtml(federation.sourceCount??0)}</strong><span>sources</span></div><div class="metric"><strong id="federation-providers">${escapeHtml(federation.providerCount??0)}</strong><span>providers</span></div><div class="metric"><strong id="federation-blockers">${escapeHtml(federation.blockerCount??0)}</strong><span>blockers</span></div></div><p class="muted">Provider instructions are not loaded here. Search resolves metadata first; external providers remain quarantined until scan, evaluation, and approval.</p><div class="toolbar"><input id="capability-query" aria-label="Search capabilities" placeholder="Search UI, testing, security, graphics, engineering…"><button id="capability-search" class="action">Search capabilities</button></div><pre id="federation-results" class="dialog" hidden></pre></section><section class="panel span12" id="skill-intelligence-panel"><div class="panel-head"><div><div class="eyebrow">Skill Intelligence</div><h2>RoutePlan and global context</h2></div><button id="intelligence-status" class="action">Refresh intelligence</button></div><div class="metrics"><div class="metric"><strong id="intelligence-outcomes">${escapeHtml(skillIntelligence.outcomeCount??0)}</strong><span>outcome scaffolds</span></div><div class="metric"><strong id="intelligence-techniques">${escapeHtml(skillIntelligence.techniqueCount??0)}</strong><span>deep techniques</span></div><div class="metric"><strong id="intelligence-l0">${escapeHtml(skillIntelligence.l0TechniqueCount??0)} L0</strong><span>kernel techniques</span></div><div class="metric"><strong id="intelligence-evaluators">${escapeHtml(skillIntelligence.evaluatorCount??0)}</strong><span>evaluators</span></div></div><p class="muted">Build a frozen RoutePlan with selected and excluded reasons. Context budget covers system, task, skill sections, code, artifacts, memory, tool output, references, output reserve, and safety reserve.</p><div class="toolbar"><input id="intelligence-query" aria-label="Route a technique" placeholder="Describe the exact problem or failure symptom…"><button id="intelligence-route" class="action primary">Explain route</button></div><pre id="intelligence-results" class="dialog" hidden></pre></section><section class="panel span12" id="v06-panel"><div class="panel-head"><div><div class="eyebrow">ForgeOS v0.6</div><h2>Deterministic Skill Fabric</h2></div><button id="v06-status" class="action">Refresh fabric status</button></div><div class="metrics"><div class="metric"><strong id="v06-kernel">${escapeHtml(v06.kernelTechniqueCount??0)}</strong><span>kernel techniques</span></div><div class="metric"><strong id="v06-l0">${escapeHtml(v06.l0TechniqueCount??0)} L0</strong><span>orchestration</span></div><div class="metric"><strong id="v06-l1">${escapeHtml(v06.l1TechniqueCount??0)} L1</strong><span>cross-domain methods</span></div><div class="metric"><strong id="v06-review">${escapeHtml(v06.reviewBenchmark?.cases??0)}</strong><span>review benchmark cases</span></div><div class="metric"><strong id="v06-security">${escapeHtml(v06.agentSurfaceAdversarial?.passed??0)}/${escapeHtml(v06.agentSurfaceAdversarial?.cases??0)}</strong><span>agent-surface adversarial</span></div></div><p class="muted">Compile hybrid skills into deterministic, agent, reflection, join, gate, retry, and rollback nodes. Security scanning covers instructions, hooks, MCP permissions, package lifecycle scripts, environment references, and egress paths.</p><div class="toolbar"><button id="v06-security-demo" class="action">Run safe surface scan</button></div><pre id="v06-results" class="dialog" hidden></pre></section></div></main></div></div><script nonce="${nonce}">
let forgeState=${embedded};const statusNode=document.getElementById('status');const controls=[...document.querySelectorAll('button')];function setBusy(busy,message){controls.forEach(button=>button.disabled=busy);statusNode.className='';statusNode.textContent=message??(busy?'Working…':'Ready.')}function show(message,tone='success'){statusNode.className=tone;statusNode.textContent=message}function unwrap(result){return result?.structuredContent??result?.result?.structuredContent??result?.result??result}let mcpSession=null,mcpReady=false,mcpId=0;async function mcpRpc(method,params,notification=false){const headers={'content-type':'application/json','accept':'application/json, text/event-stream'};if(mcpSession){headers['MCP-Session-Id']=mcpSession;headers['MCP-Protocol-Version']='${PRODUCT.protocolTargets.mcp}';}const request={jsonrpc:'2.0',method,...(params===undefined?{}:{params}),...(notification?{}:{id:++mcpId})};const response=await fetch('/mcp',{method:'POST',headers,body:JSON.stringify(request),credentials:'same-origin'});const created=response.headers.get('MCP-Session-Id');if(created)mcpSession=created;if(!response.ok)throw new Error('MCP HTTP '+response.status);if(notification)return null;const body=await response.json();if(body.error)throw new Error(body.error.message||'MCP error');return body.result}async function ensureMcp(){if(mcpReady)return;await mcpRpc('initialize',{protocolVersion:'${PRODUCT.protocolTargets.mcp}',capabilities:{},clientInfo:{name:'forge-studio-standalone',version:'${PRODUCT.version}'}});await mcpRpc('notifications/initialized',undefined,true);mcpReady=true}async function callTool(name,args){if(window.openai?.callTool)return unwrap(await window.openai.callTool(name,args));await ensureMcp();return unwrap(await mcpRpc('tools/call',{name,arguments:args}))}function applyProject(next){if(!next)return;forgeState.project=next;document.getElementById('project-name').textContent=next.name;document.getElementById('metric-stage').textContent=next.stage;document.getElementById('metric-revision').textContent='r'+next.revision+'/s'+next.semanticRevision;window.openai?.setWidgetState?.({projectId:next.id,revision:next.revision,semanticRevision:next.semanticRevision});}async function refresh(){const data=await callTool('forge_project_get',{projectId:forgeState.project.id});applyProject(data.project);show('Project refreshed. Reload the view to redraw every panel.')}async function execute(name,args,message){setBusy(true,message);try{const data=await callTool(name,args);applyProject(data.project);if(data.routes)forgeState.routes=data.routes;show(name+' completed.');return data}catch(error){show(error?.message??String(error),'error');throw error}finally{setBusy(false)}}document.getElementById('next').addEventListener('click',()=>execute('forge_next_action',{projectId:forgeState.project.id},'Computing typed route…'));document.getElementById('gate').addEventListener('click',()=>execute('forge_gate_run',{projectId:forgeState.project.id},'Evaluating current proof…'));document.getElementById('refresh').addEventListener('click',refresh);document.getElementById('project-selector').addEventListener('change',event=>{const id=event.target.value;const selected=forgeState.projects.find(project=>project.id===id);if(selected){forgeState.project=selected;applyProject(selected);refresh();}});document.getElementById('routes').addEventListener('click',async event=>{const button=event.target.closest('button[data-action]');if(!button)return;const skill=button.dataset.skill;if(button.dataset.action==='inspect'){const data=await execute('forge_skill_get',{name:skill},'Loading selected skill only…');const inspector=document.getElementById('inspector');inspector.hidden=false;inspector.textContent=data.skill.body;}else{const targetOutputs=JSON.parse(button.dataset.outputs||'[]');await execute('forge_skill_run_start',{projectId:forgeState.project.id,skillName:skill,tools:[],targetOutputs},'Leasing skill run…');}});document.getElementById('federation-audit')?.addEventListener('click',async()=>{const data=await execute('forge_federation_audit',{tenantId:forgeState.tenantId},'Auditing federation metadata…');const audit=data.audit;document.getElementById('federation-capabilities').textContent=audit.capabilityCount;document.getElementById('federation-sources').textContent=audit.sourceCount;document.getElementById('federation-providers').textContent=audit.providerCount;document.getElementById('federation-blockers').textContent=audit.blockerCount;});document.getElementById('capability-search')?.addEventListener('click',async()=>{const query=document.getElementById('capability-query').value.trim();if(!query){show('Enter a capability search query.','error');return;}const data=await execute('forge_capabilities_search',{query,limit:20},'Searching capability metadata…');const results=document.getElementById('federation-results');results.hidden=false;results.textContent=JSON.stringify(data.capabilities.map(({capabilityId,title,domain,riskClass,requiredTools})=>({capabilityId,title,domain,riskClass,requiredTools})),null,2);});document.getElementById('intelligence-status')?.addEventListener('click',async()=>{const data=await execute('forge_intelligence_status',{},'Loading Skill Intelligence graph…');for(const [id,value] of [['intelligence-outcomes',data.status.outcomeCount],['intelligence-techniques',data.status.techniqueCount],['intelligence-l0',data.status.l0TechniqueCount+' L0'],['intelligence-evaluators',data.status.evaluatorCount]])document.getElementById(id).textContent=value;});document.getElementById('intelligence-route')?.addEventListener('click',async()=>{const query=document.getElementById('intelligence-query').value.trim();if(!query){show('Describe a routing problem.','error');return;}const data=await execute('forge_intelligence_route',{query,domains:[forgeState.project.domain].filter(domain=>domain&&domain!=='all'),tools:[],assurance:forgeState.project.assurance,operation:'planning'},'Retrieving outcomes and deep techniques…');const results=document.getElementById('intelligence-results');results.hidden=false;results.textContent=JSON.stringify({routePlanId:data.routePlan.routePlanId,steps:data.routePlan.steps,inclusions:data.routePlan.inclusions,exclusions:data.routePlan.exclusions,budget:data.routePlan.budget,blockers:data.routePlan.blockers},null,2);});document.getElementById('v06-status')?.addEventListener('click',async()=>{const data=await execute('forge_v06_status',{},'Loading deterministic fabric…');const status=data.status;for(const [id,value] of [['v06-kernel',status.kernelTechniqueCount],['v06-l0',status.l0TechniqueCount+' L0'],['v06-l1',status.l1TechniqueCount+' L1'],['v06-review',status.reviewBenchmark.cases],['v06-security',status.agentSurfaceAdversarial.passed+'/'+status.agentSurfaceAdversarial.cases]])document.getElementById(id).textContent=value;});document.getElementById('v06-security-demo')?.addEventListener('click',async()=>{const data=await execute('forge_agent_surface_scan',{surface:{instructions:[],hooks:[],mcpServers:[],packages:[],allowedCommands:[],envReferences:[]}},'Scanning agent surface…');const results=document.getElementById('v06-results');results.hidden=false;results.textContent=JSON.stringify(data.report,null,2);});window.addEventListener('message',event=>{if(event.data?.type==='set_globals'&&event.data.globals?.toolOutput){const data=unwrap(event.data.globals.toolOutput);applyProject(data?.project);show('Host state synchronized.')}});
</script></body></html>`;
}
